//   Course Clips/7-4FrontGFX / layer 'Layer 2' / frame 3 /  Xtra/Blank Movieclip
// onClipEvent(enterFrame)
void clip_5203_7_1(Activation& scope) {
    if (scope.self["hitTest"](_root["Course"]["Char"]["charClip"]["body"])) {
        if (_root["PauseGame"] == false && _root["playpause"] == false) {
            //_root.Course.Char.yspeed = _root.groundFriction(_root.Course.Char.yspeed, 0.015, 1.001);
            if (scope["savezoom"] == undefined) {
                scope["savezoom"] = _root["CameraZoom"];
            }
            if (_root["CameraZoom"] > 50) {
                _root["CameraZoom"] -= 1;
            }
        }
    } else {
        if (strictNotEquals(scope["savezoom"], undefined)) {
            if (_root["CameraZoom"] < scope["savezoom"]) {
                _root["CameraZoom"] += 1;
            } else {
                scope["savezoom"] = undefined;
            }
        }
    }
}

//   Course Clips/7-5BackGFX / layer 'Layer 2' / frame 3
void frame_5148_0(Activation& scope) {
    stop();
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("righttransition2", "7-1", -900, -560, -900, -560);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

